import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788342209000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is configured through environment variables. See the <a href="/reference/environment">environment variable reference</a> for the full table.</p><h2 id="getting-a-token" tabindex="-1">Getting a token <a class="header-anchor" href="#getting-a-token" aria-label="Permalink to “Getting a token”">​</a></h2><p>In the Opengist web UI: <strong>Settings → Access Tokens → Generate new token</strong>. Opengist shows the value once; it starts with <code>og_</code>.</p><p>The server warns on startup if the token does not start with <code>og_</code>, because the most common mistake is pasting an account password instead.</p><h2 id="required-scopes" tabindex="-1">Required scopes <a class="header-anchor" href="#required-scopes" aria-label="Permalink to “Required scopes”">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>What it unlocks</th></tr></thead><tbody><tr><td><code>gist:read</code></td><td>Reading gists, including your private and unlisted ones</td></tr><tr><td><code>gist:write</code></td><td><code>create_gist</code>, <code>update_gist</code>, <code>delete_gist*</code>, <code>fork_gist</code></td></tr><tr><td><code>user:read</code></td><td><code>get_user</code></td></tr><tr><td><code>user:write</code></td><td><code>set_gist_like</code> only</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">A token without <code>gist:read</code> fails quietly</p><p>The API does not reject it. It silently returns only public gists, so your own private ones simply appear not to exist. If a gist you can see in the browser is missing from <code>list_gists</code>, check the scope first.</p></div><p>If you only want the model to read, the honest way to do it is a token with <code>gist:read</code> and <code>user:read</code> and nothing else. <code>OPENGIST_READ_ONLY=true</code> is the convenience version of the same idea — it stops the write tools from being registered at all — but it is enforced by this server, not by Opengist. See <a href="/guide/security#what-actually-holds">Security</a>.</p><h2 id="the-instance-url" tabindex="-1">The instance URL <a class="header-anchor" href="#the-instance-url" aria-label="Permalink to “The instance URL”">​</a></h2><p><code>OPENGIST_URL</code> is the root of your instance, not the API path:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">https://gist.example.com</span></span></code></pre></div><p>A trailing slash is stripped, and a trailing <code>/api</code> is accepted and removed rather than producing <code>/api/api</code>.</p><p>The server refuses to start if the URL is malformed, uses a protocol other than http/https, or contains a username or password — credentials in the URL would be sent on every request in addition to the bearer token and would surface in error messages.</p><p>Plain <code>http://</code> to anything other than a loopback address produces a warning and then continues. The token and every gist would travel unencrypted; use <code>https://</code>.</p><div class="tip custom-block"><p class="custom-block-title">Set <code>external-url</code> on the instance</p><p>If Opengist&#39;s own <code>external-url</code> (<code>OG_EXTERNAL_URL</code>) is not configured, the URLs it reports — and that this server passes through — point at <code>localhost</code>. The gists are correct, the links are useless.</p></div><h2 id="tls" tabindex="-1">TLS <a class="header-anchor" href="#tls" aria-label="Permalink to “TLS”">​</a></h2><p>For an instance with a self-signed or internal-CA certificate:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_INSECURE_TLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>This is scoped to the connection to your Opengist instance through a dedicated undici dispatcher. It does <strong>not</strong> set <code>NODE_TLS_REJECT_UNAUTHORIZED</code>, so it cannot weaken any other request the process makes, and it is only applied to requests whose origin matches <code>OPENGIST_URL</code>.</p><p>It still turns off certificate validation for that connection, which means anyone able to intercept it can read your token. Installing the CA certificate in the system trust store, or using <code>NODE_EXTRA_CA_CERTS</code>, is strictly better where it is an option.</p><h2 id="read-only-mode" tabindex="-1">Read-only mode <a class="header-anchor" href="#read-only-mode" aria-label="Permalink to “Read-only mode”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_READ_ONLY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span></code></pre></div><p>The six write tools — <code>create_gist</code>, <code>update_gist</code>, <code>delete_gist_files</code>, <code>delete_gist</code>, <code>fork_gist</code>, <code>set_gist_like</code> — are not registered. The model does not see them in <code>tools/list</code> and cannot call them, rather than being told &quot;no&quot; after asking.</p><p><code>true</code>, <code>1</code> and <code>yes</code> all turn it on, in any casing. This switch takes capability away, so it is read generously on purpose: a spelling an operator plausibly meant must not quietly leave every write tool registered. <code>OPENGIST_INSECURE_TLS</code> is the opposite case — it grants something — and there only the exact string <code>true</code> counts.</p><h2 id="turning-the-approval-dialog-off" tabindex="-1">Turning the approval dialog off <a class="header-anchor" href="#turning-the-approval-dialog-off" aria-label="Permalink to “Turning the approval dialog off”">​</a></h2><p>Deleting, and anything that widens a gist&#39;s visibility, ask a person through MCP elicitation before they act. <code>ELICITATION=false</code> takes them to the two-call token instead. It does not remove the guard; there is no setting in which a guarded call goes unannounced.</p><p>The variable deliberately carries no <code>OPENGIST_</code> prefix, which means it reaches every MCP server in the same environment, and — unlike the booleans here — a value it does not recognise <strong>stops the server</strong> rather than failing off. See <a href="/guide/approval">Asking a person</a>.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p>Read-only mode is one cut, along a line this server drew for you. <code>OPENGIST_ALLOW_TOOLS</code> and <code>OPENGIST_DENY_TOOLS</code> let you draw your own:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">list_gists,get_gist_file,create_gist</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">OPENGIST_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">delete_*</span></span></code></pre></div><p>Why bother, when all fourteen work: a model chooses the right tool far more reliably from a handful than from a long list, and every tool it can see costs context on every single request. If this is the only MCP server in a session, fourteen is fine. If it is one of six, it is not.</p><p><strong>The syntax.</strong> Comma-separated entries. An entry is either an exact tool name or a prefix with a trailing <code>*</code> — <code>list_*</code> matches every tool whose name starts with <code>list_</code>. Entries are trimmed and case-insensitive, empty ones are ignored, and an empty value counts as unset. Nothing else is a pattern: <code>*_x</code> and <code>list_*_x</code> are rejected rather than silently matching nothing.</p><p><strong><code>essential</code></strong> is a curated preset of seven:</p><p><code>list_gists</code>, <code>search_gists</code>, <code>get_gist</code>, <code>get_gist_file</code>, <code>create_gist</code>, <code>update_gist</code>, <code>delete_gist</code>.</p><p>It composes — naming a tool alongside it puts that one back, and <code>OPENGIST_DENY_TOOLS</code> takes one away.</p><p><strong>Both together.</strong> <code>OPENGIST_ALLOW_TOOLS</code> decides what is in; <code>OPENGIST_DENY_TOOLS</code> is then subtracted from the result. With only a deny list, everything else stays.</p><p><strong>A name that matches nothing stops the server</strong>, with the offending entry and the list of real names. That is deliberate: the alternative is a tool quietly missing from <code>tools/list</code>, and nobody traces an absence back to an environment variable. The same applies to a pattern that matches no tool.</p><p><strong>With read-only mode</strong>, the write tools are not registered at all, so naming one explicitly in <code>OPENGIST_ALLOW_TOOLS</code> is an error that says so — rather than calling a tool unknown when it plainly exists. A <em>pattern</em> that covers write tools is fine and simply contributes nothing, and <code>OPENGIST_ALLOW_TOOLS=essential</code> narrows to the read half of the preset.</p><div class="tip custom-block"><p class="custom-block-title">It is the same cut, not a second one</p><p>A filtered tool is never registered, so it is absent from <code>tools/list</code> and unknown to <code>tools/call</code> alike — exactly what <code>OPENGIST_READ_ONLY</code> does to a write tool. There is no &quot;hidden but callable&quot; state to reason about.</p></div>`,40)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};